import { getReportText } from "../api/interviewApi";
import { CRITERIA_LABELS, formatDate, sourceLabel } from "./formatters";

export function saveTextFile(filename, text, mime = "text/markdown") {
  const blob = new Blob([text], { type: `${mime};charset=utf-8` });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// Downloads the Markdown report generated by the backend.
export async function downloadMarkdownReport(sessionId) {
  const text = await getReportText(sessionId);
  saveTextFile(`interview-report-${sessionId}.md`, text);
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function listHtml(items) {
  if (!items || items.length === 0) return "<p>None</p>";
  return `<ul>${items.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>`;
}

// Opens a printable version of the report. Use the browser's "Save as PDF" in the print dialog.
export function printReport(detail) {
  const questions = detail.results
    .map((item, index) => {
      const q = item.question;
      if (!item.evaluation) {
        return `<h3>Q${index + 1}: ${escapeHtml(q.text)}</h3><p><em>Not answered.</em></p>`;
      }
      const ev = item.evaluation;
      const rows = Object.keys(CRITERIA_LABELS)
        .map((key) => `<tr><td>${CRITERIA_LABELS[key]}</td><td>${ev.scores[key]} / 10</td></tr>`)
        .join("");
      const pace = ev.metrics.words_per_minute
        ? `${ev.metrics.words_per_minute} words/min`
        : "not measured (typed answer)";
      return `
        <h3>Q${index + 1}: ${escapeHtml(q.text)}</h3>
        <p class="meta">Topic: ${escapeHtml(q.topic)} | Difficulty: ${escapeHtml(q.difficulty)}</p>
        <p><strong>Your answer:</strong> ${escapeHtml(item.answer_text)}</p>
        <p><strong>Score:</strong> ${ev.overall_score}/100 (${escapeHtml(ev.label)}) - ${escapeHtml(sourceLabel(ev.source))}</p>
        <table>${rows}</table>
        <p><strong>Measured:</strong> ${ev.metrics.word_count} words, ${ev.metrics.filler_count} filler words, pace ${pace}.</p>
        <p><strong>Strengths</strong></p>${listHtml(ev.feedback.strengths)}
        <p><strong>Weaknesses</strong></p>${listHtml(ev.feedback.weaknesses)}
        <p><strong>Missing concepts</strong></p>${listHtml(ev.feedback.missing_concepts)}
        <p><strong>Suggested improvements</strong></p>${listHtml(ev.feedback.improvements)}
        <p><strong>Example of a stronger answer:</strong> ${escapeHtml(ev.feedback.stronger_answer)}</p>`;
    })
    .join("<hr/>");

  const summary = detail.summary
    ? `<p><strong>Strong topics:</strong> ${escapeHtml(detail.summary.strong_topics.join(", ") || "None yet")}<br/>
       <strong>Topics to revise:</strong> ${escapeHtml(detail.summary.weak_topics.join(", ") || "None")}</p>`
    : "";

  const html = `<!doctype html><html><head><meta charset="utf-8"/>
    <title>Interview report ${detail.id}</title>
    <style>
      body{font-family:Arial,sans-serif;max-width:800px;margin:24px auto;padding:0 16px;color:#1f2937;line-height:1.5}
      h1{color:#4f46e5} table{border-collapse:collapse;margin:8px 0} td{border:1px solid #d1d5db;padding:4px 10px}
      .meta{color:#6b7280;font-size:13px} .note{background:#eef2ff;padding:10px;border-radius:6px;font-size:13px}
      hr{margin:24px 0;border:none;border-top:1px solid #e5e7eb}
    </style></head><body>
    <h1>Mock Interview Report</h1>
    <p><strong>Role:</strong> ${escapeHtml(detail.role)} | <strong>Domain:</strong> ${escapeHtml(detail.domain)}<br/>
       <strong>Level:</strong> ${escapeHtml(detail.experience_level)} | <strong>Type:</strong> ${escapeHtml(detail.interview_type)}<br/>
       <strong>Date:</strong> ${escapeHtml(formatDate(detail.created_at))} | <strong>Overall score:</strong> ${detail.overall_score}/100</p>
    <p class="note">Word counts, filler words and speaking pace are measured. Rubric scores and feedback are estimates.
    This report does not analyse facial expressions, emotions or personality, and webcam recordings are never stored by the app.</p>
    ${summary}
    <h2>Question-by-question review</h2>
    ${questions}
    </body></html>`;

  const win = window.open("", "_blank");
  if (!win) {
    throw new Error("The browser blocked the pop-up. Allow pop-ups for this site and try again.");
  }
  win.document.write(html);
  win.document.close();
  win.focus();
  setTimeout(() => win.print(), 300);
}